        print(f'{base}: not found')
        continue
    count=0
    for path in p.rglob('test*.py'):
        parts=set(path.parts)
        if any(x in parts for x in ['.cache','.git','node_modules','site-packages','__pycache__']):
            continue
        print('TEST', path)
        count+=1
        if count>100: break
